#!/usr/bin/env bash
set -euo pipefail

# Hook for post-retire logic (called after status is set to retired)
# ------------------------------------------------------------------

usage() {
    cat <<USAGE
Usage: retire.sh <path>

Hook for post-retire logic.

Options:
    --help|-h    Show this help message
USAGE
    exit 0
}

WORKTREE_DIR=""

for arg in "$@"; do
    case "$arg" in
        --help | -h) usage ;;
        *)
            if [[ -z "$WORKTREE_DIR" ]]; then
                WORKTREE_DIR="$arg"
            fi
            ;;
    esac
done

if [[ -z "$WORKTREE_DIR" ]]; then
    echo "Error: path is required" >&2
    exit 1
fi

if [[ ! "$WORKTREE_DIR" = /* ]]; then
    WORKTREE_DIR="$(cd "$WORKTREE_DIR" && pwd)"
fi

# Python handles the retire -- extend here if needed
